class UserService {
  private users: User[] = [];
  private database: Database;

  constructor(database: Database) {
    this.database = database;
  }

  async loadUsers(): Promise<void> {
    this.users = await this.database.fetchUsers();
  }

  async createUser(userData: CreateUserRequest): Promise<User> {
    const user = this.createUserObject(userData);
    await this.database.saveUser(user);
    return user;
  }

  async updateUser(id: string, updates: Partial<User>): Promise<User> {
    const user = await this.findUserById(id);
    if (!user) throw new Error('User not found');

    const updatedUser = { ...user, ...updates };
    await this.database.updateUser(id, updatedUser);
    return updatedUser;
  }

  async deleteUser(id: string): Promise<void> {
    await this.database.deleteUser(id);
  }

  private createUserObject(userData: CreateUserRequest): User {
    return {
      id: Math.random().toString(36),
      email: userData.email,
      name: userData.name,
      createdAt: new Date(),
      isActive: true
    };
  }

  private async findUserById(id: string): Promise<User | null> {
    return this.users.find(u => u.id === id) || null;
  }
}

